SQL="\n-- This is one-to-one and append-only; every cancellation references a real,\n-- still-current occurrence and preserves the mandatory task as unresolved.\nCREATE OR REPLACE FUNCTION public.m4_guard_valid_activity_cancel_insert()\nRETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$\nBEGIN\n IF NOT EXISTS (\n   SELECT 1 FROM public.activities_activityoccurrence o\n   JOIN public.onboarding_task t ON t.id=o.task_id\n   JOIN public.onboarding_onboardingcase c ON c.id=t.case_id\n   JOIN public.onboarding_caseassignment a ON a.case_id=c.id\n   JOIN public.accounts_membership m ON m.id=a.member_id\n   JOIN public.accounts_user u ON u.id=m.user_id\n   WHERE o.id=NEW.occurrence_id\n     AND t.kind IN ('ACTIVITY','INTRODUCTION','CHECK_IN')\n     AND t.execution_state='IN_PROGRESS'\n     AND c.status IN ('PRE_JOINING','ACTIVE')\n     AND o.ends_at>now()\n     AND NOT EXISTS (\n       SELECT 1 FROM public.activities_activityoccurrence later\n       WHERE later.task_id=t.id AND later.revision>o.revision)\n     AND NOT EXISTS (\n       SELECT 1 FROM public.activities_activityattendance att WHERE att.occurrence_id=o.id)\n     AND a.role=m.role\n     AND a.effective_to IS NULL\n     AND a.effective_from<=now()\n     AND m.role IN ('HR','MANAGER')\n     AND (m.role='HR' OR (m.role=t.owner_role AND a.id=t.owner_assignment_id))\n     AND m.user_id=NEW.cancelled_by_id\n     AND m.active AND m.available AND u.is_active\n )\n THEN RAISE EXCEPTION 'M4 activity cancellation requires current authorized organizer/HR and pending occurrence'\n     USING ERRCODE='23514';\n END IF;\n RETURN NEW;\nEND; $$;\n\nCREATE TRIGGER m4_activity_cancel_authority BEFORE INSERT\nON public.activities_activitycancellation FOR EACH ROW\nEXECUTE FUNCTION public.m4_guard_valid_activity_cancel_insert();\nCREATE TRIGGER m4_activity_cancel_immutable BEFORE UPDATE OR DELETE\nON public.activities_activitycancellation FOR EACH ROW\nEXECUTE FUNCTION public.m4_guard_activity_evidence();\n\n-- Retain the original M4 DB attendance authority and exclude cancelled occurrences.\nCREATE OR REPLACE FUNCTION public.m4_guard_valid_attendance_insert()\nRETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$\nDECLARE organizer_role text; taskid uuid; task_state text;\nBEGIN\n SELECT t.owner_role,t.id,t.execution_state INTO organizer_role,taskid,task_state\n FROM public.activities_activityoccurrence o\n JOIN public.onboarding_task t ON t.id=o.task_id\n WHERE o.id=NEW.occurrence_id;\n IF taskid IS NULL OR organizer_role NOT IN ('HR','MANAGER')\n   OR task_state IS DISTINCT FROM 'IN_PROGRESS'\n   OR NOT EXISTS (\n      SELECT 1 FROM public.activities_activityoccurrence o\n      WHERE o.id=NEW.occurrence_id AND o.ends_at<=now()\n        AND NOT EXISTS(\n           SELECT 1 FROM public.activities_activityoccurrence later\n           WHERE later.task_id=o.task_id AND later.revision>o.revision))\n   OR EXISTS (\n      SELECT 1 FROM public.activities_activitycancellation ca WHERE ca.occurrence_id=NEW.occurrence_id)\n   OR NOT EXISTS (\n      SELECT 1 FROM public.onboarding_task t\n      JOIN public.onboarding_caseassignment a ON a.id=t.owner_assignment_id\n      JOIN public.accounts_membership m ON m.id=a.member_id\n      WHERE t.id=taskid AND a.effective_to IS NULL\n       AND m.user_id=NEW.recorded_by_id AND m.role=organizer_role AND m.active)\n THEN RAISE EXCEPTION 'M4 unauthorized or future attendance' USING ERRCODE='23514'; END IF;\n RETURN NEW;\nEND; $$;\n\n"
